const input=($input.all()[0]||{}).json;
const body=input.body||input;
const keyword=(body.keyword||body.query||'').trim();
const SB_URL='https://kekmppsuiiokdckdeolv.supabase.co';
const SB_KEY=$env.SUPABASE_SERVICE_ROLE_KEY||'';

if(!keyword)return[{json:{found:false,error:'missing keyword'}}];

try{
  const resp=await this.helpers.httpRequest({
    method:'GET',
    url:SB_URL+'/rest/v1/category_mapping_verified?select=source_category_id,description_category_id,type_id,confidence,title&source_category_id=eq.'+encodeURIComponent(keyword)+'&order=confidence.desc&limit=3',
    headers:{apikey:SB_KEY,Authorization:'Bearer '+SB_KEY},
    json:true,timeout:10000
  });
  const rows=resp||[];
  if(rows.length>0){
    return[{json:{
      found:true,
      keyword:keyword,
      mappings:rows.map(function(r){return{
        description_category_id:parseInt(r.description_category_id),
        type_id:parseInt(r.type_id),
        confidence:r.confidence,
        title:r.title
      }})
    }}];
  }
  return[{json:{found:false,keyword:keyword,mappings:[]}}];
}catch(e){
  return[{json:{found:false,error:String(e.message||e).slice(0,100)}}];
}
